import { BunRuntime } from "@effect/platform-bun";
import * as BunServices from "@effect/platform-bun/BunServices";
import * as Effect from "effect/Effect";
import { checkDocumentation } from "./docs.boundary";

BunRuntime.runMain(checkDocumentation().pipe(Effect.provide(BunServices.layer)));
import * as Array from "effect/Array";
import * as Effect from "effect/Effect";
import * as FileSystem from "effect/FileSystem";
import * as Path from "effect/Path";
import * as Schema from "effect/Schema";

const DocumentPath = Schema.String.check(
  Schema.isPattern(/^(?!.*\.\.)(?:[a-zA-Z0-9_-]+\/)*[a-zA-Z0-9_-]+\.md$/u),
).pipe(Schema.brand("DocumentPath"));
const DocumentOwner = Schema.String.check(Schema.isPattern(/^[a-z-]+$/u)).pipe(
  Schema.brand("DocumentOwner"),
);
const RegistryJson = Schema.fromJsonString(
  Schema.Array(
    Schema.Struct({ path: DocumentPath, owner: DocumentOwner, status: Schema.Literal("current") }),
  ),
);
class DocumentationError extends Schema.TaggedError<DocumentationError>()("DocumentationError", {
  reason: Schema.Literals(["duplicate-owner", "missing-document", "empty-document"]),
}) {}

export const checkDocumentation = Effect.fn("Documentation.check")(function* () {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const root = yield* path.fromFileUrl(new URL("../..", import.meta.url));
  const raw = yield* fs.readFileString(path.join(root, "docs/documentation-map.json"));
  const registry = yield* Schema.decodeEffect(RegistryJson)(raw);
  const paths = Array.map((entry: (typeof RegistryJson.Type)[number]) => entry.path)(registry);
  if (Array.dedupe(paths).length !== registry.length) {
    return yield* new DocumentationError({ reason: "duplicate-owner" });
  }
  yield* Effect.forEach(
    registry,
    Effect.fnUntraced(function* (entry) {
      const filename = path.join(root, entry.path);
      if (!(yield* fs.exists(filename))) {
        return yield* new DocumentationError({ reason: "missing-document" });
      }
      const content = yield* fs.readFileString(filename);
      if (content.length < 40) {
        return yield* new DocumentationError({ reason: "empty-document" });
      }
    }),
    { concurrency: 1, discard: true },
  );
  yield* Effect.logInfo("Documentation owners verified", { documents: registry.length });
});

