import * as Doppler from "alchemy/Doppler";
import * as Secrets from "alchemy/Secrets";
import type { SecretsContext } from "alchemy/Secrets";
import type { StackSecrets } from "alchemy/Stack";
import { Config, ConfigProvider, Effect, Layer, Schema } from "effect";

import { decodeDocsCloudflareStackStage } from "./cloudflare/website.js";

const AppsDopplerSelection = Schema.Struct({
  config: Schema.Literals(["dev", "stg_preview", "prd"]),
  project: Schema.Literal("taxkit"),
});

// The native stage is external Alchemy input. Both secret and resource
// selection restore it through the same existing stage Schema here.
export const nativeAppsStage = (value: typeof Schema.Unknown.Type) =>
  decodeDocsCloudflareStackStage(value);

// Reuse the existing checked prod / pr-N / dev_identity stage owner. Invalid
// stages fail before the native secret provider can request any credentials.
export const nativeAppsDopplerSelection = Effect.fnUntraced(function* (
  stage: string
) {
  const checked = yield* nativeAppsStage(stage).pipe(
    Effect.mapError(
      () =>
        new Config.ConfigError(
          new ConfigProvider.SourceError({
            message: "Native app stack stage is missing or invalid",
          })
        )
    )
  );
  if (checked === "prod") {
    return AppsDopplerSelection.make({ config: "prd", project: "taxkit" });
  }
  return AppsDopplerSelection.make({
    config: checked.startsWith("pr-") ? "stg_preview" : "dev",
    project: "taxkit",
  });
});

export const nativeAppsSecrets = (({ stage }: SecretsContext) => [
  Layer.unwrap(
    nativeAppsDopplerSelection(stage).pipe(
      Effect.map((selection) => Doppler.Secrets(selection).layer)
    )
  ),
  ConfigProvider.layerAdd(
    nativeAppsStage(stage).pipe(
      Effect.map((checked) => {
        // This account's 7 October Worker inventory has no rate-limit
        // namespaces. Reserve 10078 for Production and append each checked
        // PR number for Preview; two stages must never share its counters.
        if (checked === "prod") {
          return ConfigProvider.fromUnknown({
            CALCULATOR_RATE_NAMESPACE: "10078",
          });
        }
        if (checked.startsWith("pr-")) {
          return ConfigProvider.fromUnknown({
            CALCULATOR_RATE_NAMESPACE: `10078${checked.slice(3)}`,
          });
        }
        return ConfigProvider.fromUnknown({});
      })
    ),
    { asPrimary: true }
  ),
  // Native Stack.secrets otherwise appends the shell as its highest priority.
  // Credentials still come through the native provider's credential source;
  // ambient application values cannot override the selected Doppler config.
  Secrets.ProcessEnv({ disabled: true }),
]) satisfies StackSecrets;
name: Quality

on:
  pull_request:
  push:
    branches:
      - main

permissions:
  contents: read

env:
  TAXKIT_ACTION_PIN_UPDATE_OWNER: taxkit-ci-release-maintainer

concurrency:
  group: quality-${{ github.workflow }}-${{ github.ref }}
  cancel-in-progress: true

jobs:
  quality:
    runs-on: ubuntu-latest
    timeout-minutes: 60
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 0
      - run: git show-ref --verify --quiet refs/heads/main || git branch --track main origin/main
      - uses: oven-sh/setup-bun@0c5077e51419868618aeaa5fe8019c62421857d6 # v2.2.0
        with:
          bun-version-file: .bun-version
      - id: bun-cache-path
        run: echo "path=$(bun pm cache)" >> "$GITHUB_OUTPUT"
      - id: bun-cache-restore
        uses: actions/cache/restore@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        continue-on-error: true
        with:
          path: ${{ steps.bun-cache-path.outputs.path }}
          key: bun-packages-${{ runner.os }}-${{ runner.arch }}-${{ hashFiles('.bun-version') }}-${{ hashFiles('bun.lock') }}
      - run: bun install --frozen-lockfile
      - uses: actions/cache/save@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        if: steps.bun-cache-restore.outputs.cache-hit != 'true'
        continue-on-error: true
        with:
          path: ${{ steps.bun-cache-path.outputs.path }}
          key: ${{ steps.bun-cache-restore.outputs.cache-primary-key }}
      - run: echo "PLAYWRIGHT_BROWSERS_PATH=$RUNNER_TEMP/ms-playwright" >> "$GITHUB_ENV"
      - id: playwright-identity
        run: echo "version=$(apps/web/node_modules/.bin/playwright --version | cut -d' ' -f2)" >> "$GITHUB_OUTPUT"
      - id: playwright-cache-restore
        uses: actions/cache/restore@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        continue-on-error: true
        with:
          path: ${{ env.PLAYWRIGHT_BROWSERS_PATH }}
          key: playwright-chromium-${{ runner.os }}-${{ runner.arch }}-${{ steps.playwright-identity.outputs.version }}-${{ hashFiles('bun.lock') }}
      - run: apps/web/node_modules/.bin/playwright install --with-deps chromium
      - uses: actions/cache/save@55cc8345863c7cc4c66a329aec7e433d2d1c52a9 # v6.1.0
        if: steps.playwright-cache-restore.outputs.cache-hit != 'true'
        continue-on-error: true
        with:
          path: ${{ env.PLAYWRIGHT_BROWSERS_PATH }}
          key: ${{ steps.playwright-cache-restore.outputs.cache-primary-key }}
      - run: bun run check:quality-workflow
      - name: Fetch trusted CI configuration
        id: doppler-ci
        if: github.event_name != 'pull_request' || github.event.pull_request.head.repo.full_name == github.repository
        uses: dopplerhq/secrets-fetch-action@451892f16195f9ac360e1a5bcbf0b5fd0e957534 # v2.0.0
        with:
          doppler-token: ${{ secrets.DOPPLER_CI_TOKEN }}
      - name: Check trusted CI configuration identity
        if: github.event_name != 'pull_request' || github.event.pull_request.head.repo.full_name == github.repository
        env:
          DOPPLER_CONFIG: ${{ steps.doppler-ci.outputs.DOPPLER_CONFIG }}
          DOPPLER_PROJECT: ${{ steps.doppler-ci.outputs.DOPPLER_PROJECT }}
        run: test "$DOPPLER_PROJECT" = "taxkit" && test "$DOPPLER_CONFIG" = "ci"
      - name: Run trusted Quality with remote cache
        if: github.event_name != 'pull_request' || github.event.pull_request.head.repo.full_name == github.repository
        env:
          TURBO_CACHE: local:rw,remote:rw
          TURBO_TEAM: ${{ steps.doppler-ci.outputs.TURBO_TEAM }}
          TURBO_TOKEN: ${{ steps.doppler-ci.outputs.TURBO_TOKEN }}
        run: bun run release:check -- --ci
      - name: Run fork Quality without credentials
        if: github.event_name == 'pull_request' && github.event.pull_request.head.repo.full_name != github.repository
        env:
          TURBO_CACHE: local:rw
        run: bun run release:check -- --ci
